class Node:
    def __init__(self, key, left=None, right=None):
        self.key, self.left, self.right = key, left, right

def keys_between(root, lo, hi):
    out = []
    def walk(node):
        if node is None:
            return
        if lo < node.key:            # keys >= lo may exist on the left
            walk(node.left)
        if lo <= node.key <= hi:
            out.append(node.key)
        if node.key < hi:            # keys <= hi may exist on the right
            walk(node.right)
    walk(root)
    return out
